// The one shape every source of operator attention uses: the registry (commands that failed, e-stops
// not delivered), the link, the blast engine (can't-clear), battery and data quality. The attention
// tray (UI.md) shows them; the alerting rules (TESTING.md L2.60-L2.64) decide which interrupt.
// Types only: the blast engine and the attention tray are built in parallel against this.

export type AlarmSource = 'blast' | 'registry' | 'link' | 'battery' | 'data' | 'service';

export interface AlarmRaise {
  type: 'raise';
  source: AlarmSource;
  kind: string;            // e.g. 'cant_clear', 'command_failed', 'estop_undelivered', 'controller_restart'
  key: string;             // one cause, one alarm (L2.64): the same key is the same alarm, raised once
  vehicleId: string | null;
  zoneId: string | null;
  message: string;         // in the operator's words
  action: string | null;   // the next step, e.g. "Radio the shot firer to hold the shot"
  interrupt: boolean;      // true: sound and an acknowledgement; false: visible but silent (L2.60, L2.61)
  rule: string;            // what raised it, or kept it silent, e.g. "B9" (L2.62)
  atServerMs: number;
}

export interface AlarmClear {
  type: 'clear';
  key: string;
  reason: string;          // why it cleared, e.g. "truck confirmed outside DECLINE"
  atServerMs: number;
}

export type AlarmEvent = AlarmRaise | AlarmClear;
// Is this zone clear? From belief only (CLAUDE.md invariant 6: never wrongly clear).
//
// PROVISIONAL: the blast engine (PLAN.md task 5) will own this verdict, adding "can't get out in
// time", hold-before-entry and command outcomes. Until then the UI uses this, which implements only
// invariant 6:
//   NOT_CLEAR  a live or old truck reports a position inside the zone;
//   UNSURE     otherwise, any truck whose reachable range touches the zone: silent, contradicted or
//              never heard from, or a live truck at the boundary that might already be in;
//   CLEAR      no truck might be inside.
// NOT_CLEAR and UNSURE carry the same action, because in doubt the shot is held (CONTEXT.md answer 1).
// CLEAR here says nothing about trucks that may still drive in before the zone closes.
import type { TruckView, ZoneView } from './fleet.ts';
import { age, faultWords, positionAgeMs } from './words.ts';

export type Verdict = 'CLEAR' | 'NOT_CLEAR' | 'UNSURE';

export const HOLD_THE_SHOT = 'Radio the shot firer to hold the shot';

export interface ClearanceReason {
  vehicleIds: string[];
  certainty: 'inside' | 'might';
  why: string;
}

export interface Clearance {
  zoneId: string;
  verdict: Verdict;
  action: string | null;
  reasons: ClearanceReason[]; // the certain ones first
}

export function mightBeIn(t: TruckView, zoneId: string): boolean {
  return t.range === null || t.mightBeIn.includes(zoneId);
}

export function zoneClearance(zone: ZoneView, trucks: readonly TruckView[]): Clearance {
  const inside: ClearanceReason[] = [];
  const might: ClearanceReason[] = [];
  const neverHeard: string[] = [];
  for (const t of trucks) {
    if (!mightBeIn(t, zone.zoneId)) continue;
    const extra = [faultWords(t), t.state?.value === 'ESTOPPED' ? 'e-stopped' : null].filter((x) => x !== null);
    const tail = extra.length ? `; ${extra.join('; ')}` : '';
    const reportedIn = t.position?.value.zoneId === zone.zoneId;
    switch (t.confidence) {
      case 'live':
      case 'old': {
        const fresh = t.confidence === 'old' ? ` (old ${age(positionAgeMs(t) ?? 0)})` : '';
        if (reportedIn) inside.push({ vehicleIds: [t.vehicleId], certainty: 'inside', why: `inside${fresh}${tail}` });
        else might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `at the boundary, might already be in${fresh}${tail}` });
        break;
      }
      case 'silent':
        might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `silent ${age(positionAgeMs(t) ?? 0)}: could have reached it${lastSeen(t)}${tail}` });
        break;
      case 'contradicted':
        might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `data frozen: reports moving but has not moved${lastSeen(t)}${tail}` });
        break;
      case 'unknown':
        if (t.ageMs === null) neverHeard.push(t.vehicleId);
        else might.push({ vehicleIds: [t.vehicleId], certainty: 'might', why: `no valid position: could be anywhere${tail}` });
        break;
    }
  }
  if (neverHeard.length) might.push({ vehicleIds: neverHeard, certainty: 'might', why: 'never reported: could be anywhere' });
  const verdict: Verdict = inside.length ? 'NOT_CLEAR' : might.length ? 'UNSURE' : 'CLEAR';
  return { zoneId: zone.zoneId, verdict, action: verdict === 'CLEAR' ? null : HOLD_THE_SHOT, reasons: [...inside, ...might] };
}

function lastSeen(t: TruckView): string {
  const z = t.position?.value.zoneId;
  return z ? `; last seen in ${z}` : '';
}
// What a refusal means, in the operator's words (TESTING.md L2.39). Every reason in PROTOCOL.md §4.5
// gets its own message: the distinct kinds stay distinct rather than collapsing into "rejected". A
// reason that is the control room's own fault says so, so nobody goes looking at the truck.
import type { Action, RejectReason } from './protocol.ts';

export interface RefusalContext {
  vehicleId: string;
  action: Action | string;
  holder?: string | null;         // LEASE_HELD: who is driving
  state?: string | null;          // what telemetry last said the truck was doing
  faults?: string[] | null;       // INTERLOCK_ACTIVE: which fault
  inFlight?: { action: string; sentAgoMs: number } | null; // a command of ours still on its way
}

export interface Refusal {
  reason: string;     // the protocol's reason, or our own code
  ourFault: boolean;  // a bug in the control room, not something about the truck
  retry: false;       // a refusal is never retried: the same command would be refused again
  message: string;
}

const secs = (ms: number) => `${(ms / 1000).toFixed(1)} s`;

export function refusal(reason: RejectReason | string, c: RefusalContext): Refusal {
  const v = c.vehicleId, a = c.action;
  const r = (message: string, ourFault = false): Refusal => ({ reason, ourFault, retry: false, message });
  switch (reason) {
    case 'BAD_COMMAND_ID':
      return r(`The site could not read the ID on the ${a} for ${v}. This is a fault in the control-room software, not the truck; it has been logged. Not sent again.`, true);
    case 'BAD_JSON':
      return r(`The site could not read the ${a} for ${v} at all. This is a fault in the control-room software; it has been logged. Not sent again.`, true);
    case 'MISSING_OPERATOR':
      return r(`The ${a} for ${v} went out without an operator name, so the site refused it. This is a fault in the control-room software; it has been logged.`, true);
    case 'UNKNOWN_VEHICLE':
      return r(`The site does not know a truck called ${v}.`);
    case 'UNSUPPORTED_ACTION':
      return r(`The site does not support "${a}".`, true);
    case 'INTERLOCK_ACTIVE': {
      const which = c.faults && c.faults.length > 0 ? c.faults.join(', ') : 'a fault';
      return r(`${v} is interlocked by ${which}: only an e-stop works until maintenance clears it. Faults cannot be cleared from the control room. If the fault allows limp-home, take control and drive it.`);
    }
    case 'ESTOP_ACTIVE':
      return r(`${v} is e-stopped. Clear the e-stop first; it will then hold.`);
    case 'LEASE_HELD':
      return r(`${v} is being driven by ${c.holder ?? 'another operator'}. Talk to them first; a supervisor can take control from them.`);
    case 'NOT_LEASE_HOLDER':
      return r(`You do not hold ${v}'s controls, so you cannot hand them back.`);
    case 'INVALID_STATE':
      if (c.inFlight) {
        return r(`${a} refused: the ${c.inFlight.action} sent ${secs(c.inFlight.sentAgoMs)} ago is still on its way to ${v} and cannot be called back. It will take effect within a few seconds; send ${a} after that.`);
      }
      if (a === 'RESUME' && (c.state === 'HOLDING' || c.state === 'IDLE')) {
        return r(`${v} refused RESUME although its telemetry says ${c.state}. Its reported state may be wrong (frozen data); treat its position as uncertain.`);
      }
      if (a === 'EXIT_ZONE') {
        return r(`${v} refused EXIT_ZONE: the site does not allow it in a bay, or while it is ${c.state ?? 'in its current state'}. To move it out of a bay, take control and drive it.`);
      }
      return r(`${v} cannot ${a} while it is ${c.state ?? 'in its current state'}.`);
    case 'COMMAND_ID_REUSED':
      return r(`The control room reused a command ID for ${v}'s ${a}. That is our software's fault, not the truck's; it has been logged and will not be retried.`, true);
    default:
      return r(`The site refused the ${a} for ${v} (${reason}).`);
  }
}
// Plain-words formatting shared by the clearance rule and the UI. Pure: no clock, no DOM.
import type { TruckView } from './fleet.ts';

// Whole seconds, counted down from the true age so "old 2 s" never claims more freshness than it has
// lost: 2.9 s is "2 s", and the next second shows when it is reached. Minutes past 90 s.
export function age(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  if (s < 90) return `${s} s`;
  const m = Math.floor(s / 60);
  if (m < 90) return `${m} min ${s % 60} s`;
  return `${Math.floor(m / 60)} h ${m % 60} min`;
}

// A countdown as m:ss. Rounded up: "0:01" until the moment itself, never "0:00" early.
export function countdown(ms: number): string {
  const s = Math.max(0, Math.ceil(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

// Time since something, as m:ss. Rounded down, like age: "closed 0:03 ago" at 3.9 s.
export function elapsed(ms: number): string {
  const s = Math.max(0, Math.floor(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`;
}

// How old the truck's position is: since the last valid position, or since the last message if it
// never sent one.
export function positionAgeMs(t: TruckView): number | null {
  return t.position?.ageMs ?? t.ageMs;
}

// The data state in words, as the fleet table shows it (UI.md: "live, old 4 s, silent 32 s,
// contradicted").
export function dataState(t: TruckView): string {
  const a = positionAgeMs(t);
  switch (t.confidence) {
    case 'live': return 'live';
    case 'old': return `old ${age(a ?? 0)}`;
    case 'silent': return `silent ${age(a ?? 0)}`;
    case 'contradicted': return 'contradicted';
    case 'unknown': return t.ageMs === null ? 'never reported' : 'no position';
  }
}

export function faultWords(t: TruckView): string | null {
  const f = t.faults?.value ?? [];
  return f.length ? `faulted (${f.join(', ')})` : null;
}
