.chip { transition: transform 200ms linear; }
.chip.jump { transition: none; }
@media (prefers-reduced-motion: reduce) { .chip { transition: none; } }
.chip rect { fill: var(--truck-fill); stroke: var(--truck); stroke-width: 2; rx: 5; }
