import type { AlarmItem } from '../attention.ts';
import { elapsed } from '../words.ts';

export interface TrayEntry {
  key: string;
  interrupt: boolean;
  state: 'needs-ack' | 'resolved-needs-ack' | 'acknowledged' | 'silent';
  vehicleId: string | null;
  message: string;
  action: string | null;
